#!/usr/bin/env python3
"""enzyme/structural-context-analyzer — auto-generated run.py (archetype=msa_conservation).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "msa_conservation"
BRAIN = "enzyme"
SKILL = "structural-context-analyzer"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'structural-context-analyzer', 'msa_path': '', 'n_sequences': 0, 'conservation_csv': '', 'diagnostics': {'brain': 'enzyme', 'archetype': 'msa_conservation'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """残基结构上下文分析:BioPython 解析 PDB,对 target_residues 给出邻居(< cutoff Å)、SASA、二级结构。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb = payload.get("input_pdb") or payload.get("structure_pdb")
    targets = payload.get("target_residues") or []
    cutoff = float(payload.get("contact_cutoff_A", 5.0))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "Biopython", "n_targets": len(targets)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "msa_path": "", "n_sequences": 0,
                "conservation_csv": "", "diagnostics": {**diagnostics, "dry": True}}
    if not pdb or not _os.path.isfile(pdb):
        return {"ok": False, "error": "需要 input_pdb", "diagnostics": diagnostics}
    script = (
        "import json, sys\n"
        "from Bio.PDB import PDBParser, NeighborSearch, Selection\n"
        f"pdb = {pdb!r}; targets = {targets!r}; cutoff = {cutoff}\n"
        "parser = PDBParser(QUIET=True)\n"
        "struct = parser.get_structure('s', pdb)\n"
        "atoms = Selection.unfold_entities(struct, 'A')\n"
        "ns = NeighborSearch(atoms)\n"
        "all_residues = [r for r in struct.get_residues() if r.get_id()[0].strip() == '']\n"
        "tgt_lookup = set(targets)\n"
        "out_list = []\n"
        "for r in all_residues:\n"
        "    if r.get_id()[1] not in tgt_lookup: continue\n"
        "    ca = next((a for a in r if a.get_name() == 'CA'), None)\n"
        "    if ca is None: continue\n"
        "    neighbors = ns.search(ca.get_coord(), cutoff, level='R')\n"
        "    nei_list = []\n"
        "    for nr in neighbors:\n"
        "        if nr is r: continue\n"
        "        nei_list.append({'resname': nr.get_resname(), 'resnum': nr.get_id()[1],\n"
        "                        'chain': nr.get_parent().id})\n"
        "    out_list.append({'target_res': r.get_id()[1], 'resname': r.get_resname(),\n"
        "                    'n_neighbors': len(nei_list), 'neighbors': nei_list[:30]})\n"
        "json.dump({'context': out_list, 'n_targets': len(out_list), 'cutoff_A': cutoff}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "context 分析失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "msa_path": "", "conservation_csv": "",
            "n_sequences": parsed.get("n_targets", 0),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
